        )
    }

    override fun allocationSize(value: SessionStatusRecord) = (
            FfiConverterString.allocationSize(value.`state`) +
            FfiConverterOptionalString.allocationSize(value.`principal`) +
            FfiConverterOptionalULong.allocationSize(value.`expiresAtMs`)
    )

    override fun write(value: SessionStatusRecord, buf: ByteBuffer) {
            FfiConverterString.write(value.`state`, buf)
            FfiConverterOptionalString.write(value.`principal`, buf)
            FfiConverterOptionalULong.write(value.`expiresAtMs`, buf)
    }
}





/**
 * Errors exposed by the UniFFI bindings.
 */
sealed class AuthException: kotlin.Exception() {
    
    /**
     * The options handed to a call are not usable.
     */
    class InvalidOptions(
        
        val v1: kotlin.String
        ) : AuthException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * A storage medium failed.
     */
    class Storage(
        
        val v1: kotlin.String
        ) : AuthException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * The signer (identity provider) failed or refused.
     */
    class Signer(
        
        val v1: kotlin.String
        ) : AuthException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * An agent or canister call failed.
     */
    class Agent(
        
        val v1: kotlin.String
        ) : AuthException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * A sign-in exists for this domain, but this client holds no credential.
     */
    class SessionNotHeld(
        ) : AuthException() {
        override val message
            get() = ""
    }
    
    /**
     * The session behind the identity no longer exists.
     */
    class SessionGone(
        ) : AuthException() {
        override val message
            get() = ""
    }
    
    /**
     * A later sign-in or sign-out took over from this one.
     */
    class Superseded(
        
        val v1: kotlin.String
        ) : AuthException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * The platform cannot do what was asked.
     */
    class Unsupported(
        
        val v1: kotlin.String
        ) : AuthException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * Anything else.
     */
    class Message(
        
        val v1: kotlin.String
        ) : AuthException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AuthException> {
        override fun lift(error_buf: RustBuffer.ByValue): AuthException = FfiConverterTypeAuthError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeAuthError : FfiConverterRustBuffer<AuthException> {
    override fun read(buf: ByteBuffer): AuthException {
        

        return when(buf.getInt()) {
            1 -> AuthException.InvalidOptions(
                FfiConverterString.read(buf),
                )
            2 -> AuthException.Storage(
                FfiConverterString.read(buf),
                )
            3 -> AuthException.Signer(
                FfiConverterString.read(buf),
                )
            4 -> AuthException.Agent(
                FfiConverterString.read(buf),
                )
            5 -> AuthException.SessionNotHeld()
            6 -> AuthException.SessionGone()
            7 -> AuthException.Superseded(
                FfiConverterString.read(buf),
                )
            8 -> AuthException.Unsupported(
                FfiConverterString.read(buf),
                )
            9 -> AuthException.Message(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AuthException): ULong {
        return when(value) {
            is AuthException.InvalidOptions -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is AuthException.Storage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is AuthException.Signer -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is AuthException.Agent -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is AuthException.SessionNotHeld -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is AuthException.SessionGone -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is AuthException.Superseded -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is AuthException.Unsupported -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is AuthException.Message -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: AuthException, buf: ByteBuffer) {
        when(value) {
            is AuthException.InvalidOptions -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is AuthException.Storage -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is AuthException.Signer -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is AuthException.Agent -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is AuthException.SessionNotHeld -> {
                buf.putInt(5)
                Unit
            }
            is AuthException.SessionGone -> {
                buf.putInt(6)
                Unit
            }
            is AuthException.Superseded -> {
                buf.putInt(7)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is AuthException.Unsupported -> {
                buf.putInt(8)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is AuthException.Message -> {
                buf.putInt(9)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalULong: FfiConverterRustBuffer<kotlin.ULong?> {
    override fun read(buf: ByteBuffer): kotlin.ULong? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterULong.read(buf)
    }

    override fun allocationSize(value: kotlin.ULong?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterULong.allocationSize(value)
        }
    }

    override fun write(value: kotlin.ULong?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterULong.write(value, buf)
        }
    }
}




